  const lesson = authored ? authored.split("\n") : [];
  const summary = uniqueSupplementLines(section.synthesis ? [section.synthesis] : [], lesson);
  const keyPoints = uniqueSupplementLines(section.keyPoints, [...lesson, ...summary]);
  const pitfalls = uniqueSupplementLines(section.misconceptions, [...lesson, ...summary, ...keyPoints]);
  const current = book.currentSectionId === section.id;
  const commitWarnings: string[] = [];
  if (section.lessonCommit && section.learnQuality?.reviews) {
    for (const review of section.learnQuality.reviews) {
      if (review.failure) {
        commitWarnings.push(`> [!warning] Not independently reviewed: ${review.role} (${review.failure.code})`);
      }
      if (review.role === "visual" && review.findings.some(f => f.issue === "Figures were not visually checked (text-only model).")) {
        commitWarnings.push("> [!warning] Figures were not visually checked (text-only model).");
      }
    }
  }
  const lessonLines = commitWarnings.length ? [...commitWarnings, "", ...lesson] : lesson;
  const content = [
    ...(lessonLines.length ? block("## Lesson", lessonLines) : [section.synthesis?.trim()
      ? "A recap is saved below. The full explanation has not been saved yet."
      : "This section is ready. The lesson will appear as you work through it.", ""]),
    ...supplementalSourceFigureLines(config, book, notePath, section.snapshots || [], authored),
    ...collapsedRecord("Recap and pitfalls", [
      ...block("### Section summary", summary),
      ...block("### Key points", keyPoints.map((point) => `- ${point}`)),
      ...block("### Common pitfalls", pitfalls.map((point) => `- ${point}`)),
    ]),
    ...collapsedRecord("Learning record", [
      ...block("### Learning objectives", objectives),
      ...block("### Understanding checks", checks),
      ...block("### Remaining work", otherRemaining.map(item => `- ${markdownText(item)}`)),
    ]),
    // The chapter link travels with the metadata appendix below the lesson, so
    // the generated note opens with the status line and the teaching itself.
    wikiLink(notePath, chapterNotePath(config, book, chapter), chapterLabel), "",
    ...assessmentQuestionBlock(section.attempts),
  ];
  const status = [
    statusLabel(section.status),
    current ? "Current section" : "",
    pageRange(section.startPage, section.endPage),
    section.status === "complete" ? "Section complete · reopen for practice anytime"
      : pendingChecks ? `${pendingChecks} short ${pendingChecks === 1 ? "question" : "questions"} remaining` : lessonProgress,
  ].filter(Boolean).join(" · ");
  return generatedDocument(frontmatter([
    "type: scholar-section", `book_id: ${yaml(book.id)}`, `chapter_id: ${yaml(chapter.id)}`, `section_id: ${yaml(section.id)}`,
    `status: ${yaml(section.status)}`, `current: ${current}`, `created: ${yaml(section.createdAt)}`, `updated: ${yaml(section.updatedAt)}`,
  ]), [
    `> [!scholar-status] ${status}`, "",
    ...(content.some((line) => line.trim()) ? content : ["This section is ready. Notes will appear as you work through it."]),
  ].join("\n"));
}

