import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { Type } from "typebox";
import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import { extractSourcePages, renderPdfPage } from "./ingest.ts";
import { safePathWithinRoot } from "./storage.ts";
import { snapshotAssetPath } from "./obsidian-paths.ts";
import { learnReviewHash, lessonHash, validLessonEntries } from "./lesson.ts";
import {
  isReviewReceipt,
  type ReviewBatchPass,
  type ReviewReceipt,
  type ReviewRole,
  type ReviewerVerdict,
  type ReviewFailure,
} from "./learn-quality.ts";
import {
  DEFAULT_REVIEWER_LIMITS,
  runReviewer,
  ReviewerRunError,
  type ReviewerTool,
  type ReviewerProgress,
} from "./review-runtime.ts";
import type { ExamQuestion, ScholarBook, ScholarConfig, ScholarExam, ScholarSection, ScholarSnapshot, TutorSession } from "./types.ts";
import { examBlueprint } from "./exam.ts";

export type ReviewPacketRole = ReviewRole;

export type ReviewPacket = {
  role: ReviewPacketRole;
  id: string; // unique within one pass
  instruction: string; // scoped task
  reads: number[];
  views: number[];
  cropIds: string[];
  payload: Record<string, unknown>; // only this packet's passages
};

export type ReviewEvidence = {
  read(start: number, end: number): Promise<string>;
  view(page: number): Promise<{ data: string; mimeType: "image/png" }>;
  crop(id: string): Promise<{ data: string; mimeType: "image/png" }>;
};

/** Bound readers never expose a path chosen by a model or any write tool. */
export function createReviewEvidence(
  config: ScholarConfig,
  book: ScholarBook,
  snapshots?: ScholarSnapshot[],
): ReviewEvidence {
  return {
    read: (start, end) => extractSourcePages(book, start, end, 160_000, true),
    view: (page) => renderPdfPage(book, page),
    crop: async (id) => {
      const snapshot = snapshots?.find((item) => item.id === id);
      if (!snapshot) throw new Error("Unknown saved source figure.");
      const path = await safePathWithinRoot(config.obsidianRoot, snapshotAssetPath(config, book, snapshot));
      const bytes = await readFile(path);
      if (createHash("sha256").update(bytes).digest("hex") !== snapshot.sha256) {
        throw new Error("Saved figure bytes changed; the review is invalid.");
      }
      return { data: bytes.toString("base64"), mimeType: "image/png" };
    },
  };
}

/** Replaced/unused crops remain in the note's history but are not current review work. */
export function currentReviewSnapshots(section: import("./types.ts").ScholarSection, sourceHash: string): ScholarSnapshot[] {
  const ids = new Set(validLessonEntries(section, sourceHash).flatMap(entry => entry.lesson!.embeddedSnapshotIds || []));
  for (const page of section.figureCoverage?.pages || []) {
    for (const figure of page.review?.figures || []) if (figure.snapshotId) ids.add(figure.snapshotId);
  }
  return (section.snapshots || []).filter(snapshot => ids.has(snapshot.id));
}

export const REVIEW_CONCURRENCY = 12;
/** Reviewers never inherit the learner's reasoning level: an audit is deliberately a
 * shallow, fast second pass over evidence, not a second attempt at the lesson. */
export const REVIEWER_THINKING_LEVEL = "low" as const;
export const REVIEW_CHECKPOINT_MESSAGE = "Review in progress; finished checks are saved and will be reused.";

export const REVIEW_INSTRUCTIONS: Record<ReviewRole, string> = {
  source: `Compare the ENTIRE scoped source against the lesson and its sourceCoverage checklist. Independently identify missing essential content even if the author omitted it from the checklist. Check definitions, derivations, boundary conditions, assumptions, worked examples and counterexamples. Check the actual saved explanation, not objective labels. Reject misleading generalizations and recap inaccuracies. Cite exact source pages and the missing or incorrect passage. Complete source reading is required before a pass. Distinguish the section's actual explanations from exercises assigned to the reader and prerequisites covered earlier; do not require solutions to every exercise or rederivation of earlier chapters. Check any added worked application for co…
  teaching: `Evaluate the lesson as instruction for an intelligent adult learning this material, not a compressed summary for an expert. Require unfamiliar technical terms and symbols to be explained at first meaningful use; motivation, intermediate reasoning and assumptions at difficult steps; examples or figure walkthroughs where they carry the explanation. Reject a wall of facts, unexplained jumps, unhelpful analogies or a gallery replacing explanation. Trace the hardest transitions yourself: can a learner obtain the next equation from the stated components, signs, substitutions and assumptions? For each blocking finding name the exact passage and missing connection and give a concrete repair, not "add detail". A named figure or term is not an explanation…
  visual: `Inspect every saved crop listed below against the source text and figure inventory you were given. Check complete arrows, axis labels, units, signs, legends, geometry and limiting behavior. Compare each caption and adjacent explanation against what the image actually shows; work out simple sign or limit checks when relevant. Central equations must appear in expanded native Key equation callouts with definitions, assumptions and meaning; intermediate algebra may remain outside boxes. Reject raw/broken LaTeX, inconsistent vector notation, incorrect equations and decorative or misleading diagrams. Judge each crop on the evidence you have: you cannot see the full page, so report a suspected crop edge as advice unless the crop itself hides required con…
  assessment: `Review this frozen proposed question BEFORE the learner sees it. Check the source and taught lesson, focused grounding, appropriate check kind, unambiguous wording, unique correct answer (or exact multi-select set), calculation/units, fair distractors and a sufficient grading rubric. Inspect every option description and prompt/context for answer cues; a unique explanatory hint on the correct option is a defect. Diagnostic questions may probe prerequisites before teaching, but cannot claim mastery. Practice on a completed section must not add earned-progress requirements. Reject unexplained new terminology and unsupported demands. Never alter the grading key; return concrete repairs to the author. Report at most six blocking findings, the most …
};

export function blocking(issue: string, target = "review evidence"): ReviewerVerdict {
  return {
    status: "changes",
    findings: [{
      severity: "blocking",
      target,
      sourcePages: [],
      issue,
      repair: "Inspect the required evidence and rerun this review; do not treat unavailable or incomplete review as approval.",
    }],
  };
}

/** Pi resolves a provider adapter lazily, and a minimal injected registry may offer none.
 * Reviewers request their fixed reasoning level only where the adapter can receive it. */
function reasoningCapableProvider(registry: ExtensionContext["modelRegistry"], providerId: string): boolean {
  try {
    const provider = registry.getProvider?.(providerId) as { streamSimple?: unknown } | undefined;
    return typeof provider?.streamSimple === "function" && typeof registry.getApiKeyAndHeaders === "function";
  } catch {
    return false;
  }
}

/** The reviewer identity stamped on every receipt: a changed model invalidates old checks. */
export function reviewerModelName(ctx: ExtensionContext): string {
  return ctx.model ? `${ctx.model.provider}/${ctx.model.id}` : "unavailable";
}

export function pageRuns(pages: readonly number[]): Array<[number, number]> {
  const runs: Array<[number, number]> = [];
  for (const page of [...new Set(pages)].sort((a, b) => a - b)) {
    const last = runs.at(-1);
    if (last && page === last[1] + 1 && page - last[0] < 8) last[1] = page;
    else runs.push([page, page]);
  }
  return runs;
}

export function uniqueBatches(batches: ReviewBatchPass[]): ReviewBatchPass[] {
  return [...new Map(batches.map((batch) => [batch.key, batch])).values()].slice(0, 128);
}

export function aggregateReviews(results: ReviewReceipt[]): ReviewReceipt {
  const findings = [...new Map(results.flatMap((result) => result.findings).map((finding) => [JSON.stringify(finding), finding])).values()];
…
}

